def _svg(body: str, style: str = "") -> str:
    return (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {VIEW} {VIEW}">'
            + (f"<style>{style}</style>" if style else "") + body + "</svg>")


def main(cloud: str, ink: str, style: str = "") -> str:
    """The ɛλicit icon. Colours are SVG paint values; with style, class names can be used."""
    return _svg(f'<path fill="{ink}" class="ink" d="{LETTERS}"/>'
                f'<path fill="{cloud}" class="cloud" d="{CLOUD}"/>', style)


def waiting(cloud: str, ink: str, drops: str) -> str:
    """Recordings waiting for review: a grey cloud, rain in the theme colour."""
    rain = "".join(f'<ellipse cx="{x}" cy="{y}" rx="{DROP_RX}" ry="{DROP_RY}" '
                   f'transform="rotate({DROP_ROTATE})"/>' for x, y in DROPS)
    return _svg(f'<g transform="{WAITING_TRANSFORM}">'
                f'<path fill="{ink}" d="{WAITING_LETTERS}"/><path fill="{cloud}" d="{WAITING_CLOUD}"/></g>'
                f'<g fill="{drops}" transform="{WAITING_SHIFT}">{rain}</g>')


LOGO_VIEW = "3.1 10.2 27.6 13.3"        # the wordmark's own box (measured from the drawing)
LOGO_RATIO = 27.6 / 13.3


def logo_layer(part: str, fill: str) -> str:
    """One layer of the wordmark in its own box, for drawing it where SVG clip paths aren't
    available (Qt): "cloud" or "letters", in one colour."""
    d = LOGO_CLOUD if part == "cloud" else LOGO_LETTERS
    return (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{LOGO_VIEW}">'
            f'<g transform="{LOGO_TRANSFORM}"><path fill="{fill}" d="{d}"/></g></svg>')


def logo(cloud: str, ink: str, on_cloud: str = "#ffffff", style: str = "") -> str:
    """The wordmark: the letters in ink, and white where they lie on the cloud."""
    return _svg(f'<defs><clipPath id="c"><path d="{LOGO_CLOUD}"/></clipPath></defs>'
                f'<g transform="{LOGO_TRANSFORM}">'
                f'<path fill="{cloud}" class="cloud" d="{LOGO_CLOUD}"/>'
                f'<path fill="{ink}" class="ink" d="{LOGO_LETTERS}"/>'
                f'<path fill="{on_cloud}" clip-path="url(#c)" d="{LOGO_LETTERS}"/></g>', style)
